const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showError(error) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = document.createElement('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = error.message;
}

function validRangeDate(value) {
  if (value === '') return true;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

function appendProject(project, onArchive) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'Open project';
  button.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    app.querySelector('[role="alert"]')?.remove();
    archive.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      onArchive();
    } catch (error) { archive.disabled = false; showError(error); }
  });
  row.append(name, summary, button, archive);
  app.querySelector('#projects').append(row);
  app.querySelector('#empty').hidden = true;
}

function renderRename(project) {
  const form = document.createElement('form');
  form.innerHTML = `
    <label for="new-project-name">New project name</label>
    <div class="create-controls">
      <input id="new-project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Rename project</button>
    </div>`;
  const input = form.querySelector('input');
  const submit = form.querySelector('button');
  input.disabled = project.archived;
  submit.disabled = project.archived;
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (submit.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    if (!input.value.trim()) return showError(new Error('Project name is required'));
    submit.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      Object.assign(project, saved);
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = '';
      input.focus();
    } catch (error) { showError(error); }
    finally { submit.disabled = project.archived; }
  });
  app.append(form);
}

function renderDefaultPriority(project) {
  const controls = document.createElement('div');
  controls.innerHTML = `
    <label for="default-task-priority">Default task priority</label>
    <select id="default-task-priority">
      <option value="Low">Low</option>
      <option value="Normal">Normal</option>
      <option value="High">High</option>
    </select>`;
  const select = controls.querySelector('select');
  select.value = project.default_priority;
  select.disabled = project.archived;
  select.addEventListener('change', async () => {
    if (select.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    select.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_priority: select.value }),
      });
      Object.assign(project, saved);
    } catch (error) { showError(error); }
    finally {
      select.value = project.default_priority;
      select.disabled = project.archived;
    }
  });
  app.append(controls);
}

async function renderTasks(project) {
  const projectId = project.id;
  const section = document.createElement('section');
  section.innerHTML = `
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <h2>Tasks</h2>
    <label for="task-filter">Task filter</label>
    <select id="task-filter">
      <option value="all">All</option>
      <option value="open">Open</option>
      <option value="completed">Completed</option>
    </select>
    <label for="priority-filter">Priority filter</label>
    <select id="priority-filter">
      <option value="all">All</option>
      <option value="Low">Low</option>
      <option value="Normal">Normal</option>
      <option value="High">High</option>
    </select>
    <form id="due-range">
      <label for="due-from">Due from</label>
      <input id="due-from" type="text" autocomplete="off">
      <label for="due-through">Due through</label>
      <input id="due-through" type="text" autocomplete="off">
      <button type="submit">Apply due range</button>
    </form>
    <p id="empty-tasks">No tasks to show.</p>
    <ul id="tasks" aria-label="Tasks"></ul>`;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const submit = form.querySelector('button');
  const filter = section.querySelector('#task-filter');
  const priorityFilter = section.querySelector('#priority-filter');
  const rangeForm = section.querySelector('#due-range');
  const dueFrom = section.querySelector('#due-from');
  const dueThrough = section.querySelector('#due-through');
  let appliedFrom = '';
  let appliedThrough = '';
  const list = section.querySelector('ul');
  const endpoint = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  let destinations = [];

  function drawTasks() {
    list.replaceChildren();
    const visible = tasks.filter((task) =>
      (filter.value === 'all' ||
        (filter.value === 'completed' ? task.completed : !task.completed)) &&
      (priorityFilter.value === 'all' || task.priority === priorityFilter.value) &&
      ((!appliedFrom && !appliedThrough) || (task.due_date !== '' &&
        (!appliedFrom || task.due_date >= appliedFrom) &&
        (!appliedThrough || task.due_date <= appliedThrough))));
    section.querySelector('#empty-tasks').hidden = visible.length > 0;
    for (const task of visible) {
      const row = document.createElement('li');
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        app.querySelector('[role="alert"]')?.remove();
        checkbox.disabled = true;
        try {
          const saved = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, saved);
          drawTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          showError(error);
        }
      });
      const renameForm = document.createElement('form');
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      renameLabel.textContent = 'New task title';
      const renameControls = document.createElement('div');
      renameControls.className = 'create-controls';
      const renameInput = document.createElement('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.type = 'text';
      renameInput.name = 'title';
      renameInput.autocomplete = 'off';
      renameInput.disabled = project.archived;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameButton.disabled = project.archived;
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (renameButton.disabled) return;
        app.querySelector('[role="alert"]')?.remove();
        if (!renameInput.value.trim()) return showError(new Error('Task title is required'));
        renameButton.disabled = true;
        try {
          const saved = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: renameInput.value }),
          });
          Object.assign(task, saved);
          title.textContent = task.title;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          renameInput.value = '';
          renameInput.focus();
        } catch (error) { showError(error); }
        finally { renameButton.disabled = project.archived; }
      });
      renameControls.append(renameInput, renameButton);
      renameForm.append(renameLabel, renameControls);
      const priorityControls = document.createElement('div');
      const priorityLabel = document.createElement('label');
      priorityLabel.htmlFor = `task-priority-${task.id}`;
      priorityLabel.textContent = 'Task priority';
      const priority = document.createElement('select');
      priority.id = priorityLabel.htmlFor;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        priority.append(option);
      }
      priority.value = task.priority;
      priority.disabled = project.archived;
      priority.addEventListener('change', async () => {
        app.querySelector('[role="alert"]')?.remove();
        priority.disabled = true;
        try {
          const saved = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          });
          Object.assign(task, saved);
          drawTasks();
        } catch (error) { showError(error); }
        finally {
          priority.value = task.priority;
          priority.disabled = project.archived;
        }
      });
      priorityControls.append(priorityLabel, priority);
      const dueForm = document.createElement('form');
      const dueLabel = document.createElement('label');
      dueLabel.htmlFor = `task-due-date-${task.id}`;
      dueLabel.textContent = 'Task due date';
      const dueControls = document.createElement('div');
      dueControls.className = 'create-controls';
      const dueInput = document.createElement('input');
      dueInput.id = dueLabel.htmlFor;
      dueInput.type = 'text';
      dueInput.name = 'due_date';
      dueInput.autocomplete = 'off';
      dueInput.value = task.due_date;
      dueInput.disabled = project.archived;
      const dueButton = document.createElement('button');
      dueButton.type = 'submit';
      dueButton.textContent = 'Save due date';
      dueButton.disabled = project.archived;
      dueForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (dueButton.disabled) return;
        app.querySelector('[role="alert"]')?.remove();
        dueButton.disabled = true;
        try {
          const saved = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ due_date: dueInput.value }),
          });
          Object.assign(task, saved);
          dueInput.value = task.due_date;
          drawTasks();
        } catch (error) { showError(error); }
        finally { dueButton.disabled = project.archived; }
      });
      dueControls.append(dueInput, dueButton);
      dueForm.append(dueLabel, dueControls);
      const moveForm = document.createElement('form');
      const destinationLabel = document.createElement('label');
      destinationLabel.htmlFor = `destination-project-${task.id}`;
      destinationLabel.textContent = 'Destination project';
      const destinationSelect = document.createElement('select');
      destinationSelect.id = destinationLabel.htmlFor;
      for (const destination of destinations) {
        const option = document.createElement('option');
        option.value = String(destination.id);
        option.textContent = destination.name;
        destinationSelect.append(option);
      }
      const moveButton = document.createElement('button');
      moveButton.type = 'submit';
      moveButton.textContent = 'Move task';
      destinationSelect.disabled = project.archived || destinations.length === 0;
      moveButton.disabled = destinationSelect.disabled;
      moveForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (moveButton.disabled) return;
        app.querySelector('[role="alert"]')?.remove();
        moveButton.disabled = true;
        destinationSelect.disabled = true;
        try {
          await request(`${endpoint}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ destination_project_id: Number(destinationSelect.value) }),
          });
          tasks = tasks.filter((item) => item.id !== task.id);
          drawTasks();
        } catch (error) { showError(error); }
        finally {
          destinationSelect.disabled = project.archived || destinations.length === 0;
          moveButton.disabled = destinationSelect.disabled;
        }
      });
      moveForm.append(destinationLabel, destinationSelect, moveButton);
      row.append(title, checkbox, priorityControls, renameForm, dueForm, moveForm);
      list.append(row);
    }
  }

  filter.addEventListener('change', drawTasks);
  priorityFilter.addEventListener('change', drawTasks);
  rangeForm.addEventListener('submit', (event) => {
    event.preventDefault();
    app.querySelector('[role="alert"]')?.remove();
    const from = dueFrom.value.trim();
    const through = dueThrough.value.trim();
    if (!validRangeDate(from) || !validRangeDate(through)) {
      return showError(new Error('Due range must use valid YYYY-MM-DD dates'));
    }
    if (from && through && from > through) {
      return showError(new Error('Due from must not be after Due through'));
    }
    appliedFrom = from;
    appliedThrough = through;
    dueFrom.value = from;
    dueThrough.value = through;
    drawTasks();
  });
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (submit.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    if (!input.value.trim()) return showError(new Error('Task title is required'));
    submit.disabled = true;
    try {
      const task = await request(endpoint, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      });
      tasks.push(task);
      drawTasks();
      input.value = '';
      input.focus();
    } catch (error) { showError(error); }
    finally { submit.disabled = project.archived; }
  });
  try {
    const [savedTasks, projects] = await Promise.all([request(endpoint), request('/api/projects')]);
    tasks = savedTasks;
    destinations = projects.filter((item) => !item.archived && item.id !== projectId);
    drawTasks();
    submit.disabled = project.archived;
  } catch (error) { showError(error); }
}

async function render() {
  const projectPath = window.location.pathname.match(/^\/projects\/(\d+)$/);
  if (projectPath) {
    app.innerHTML = '<button type="button" id="back">Projects</button><h1>Loading project…</h1>';
    app.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    try {
      const project = await request(`/api/projects/${projectPath[1]}`);
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      if (project.archived) {
        const notice = document.createElement('p');
        notice.textContent = 'Archived project';
        app.append(notice);
      }
      renderRename(project);
      renderDefaultPriority(project);
      await renderTasks(project);
    } catch (error) {
      app.querySelector('h1').textContent = 'Project unavailable';
      showError(error);
    }
  } else {
    app.innerHTML = `
      <h1>Workboard</h1>
      <form>
        <label for="project-name">Project name</label>
        <div class="create-controls">
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
        </div>
      </form>
      <h2>Projects</h2>
      <label for="project-filter">Project filter</label>
      <select id="project-filter">
        <option value="active">Active</option>
        <option value="archived">Archived</option>
      </select>
      <p id="empty">No projects yet.</p>
      <ul id="projects" aria-label="Projects"></ul>`;
    const form = app.querySelector('form');
    const input = app.querySelector('input');
    const submit = form.querySelector('button');
    const filter = app.querySelector('#project-filter');
    let projects = [];
    function drawProjects() {
      app.querySelector('#projects').replaceChildren();
      const visible = projects.filter((project) => project.archived === (filter.value === 'archived'));
      app.querySelector('#empty').hidden = visible.length > 0;
      app.querySelector('#empty').textContent = 'No projects to show.';
      visible.forEach((project) => appendProject(project, drawProjects));
    }
    filter.addEventListener('change', drawProjects);
    // Register after loading so creations always follow the persisted rows.
    try {
      submit.disabled = true;
      projects = await request('/api/projects');
      drawProjects();
    } catch (error) { showError(error); }
    finally { submit.disabled = false; }
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      app.querySelector('[role="alert"]')?.remove();
      if (!input.value.trim()) return showError(new Error('Project name is required'));
      submit.disabled = true;
      try {
        const project = await request('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: input.value }),
        });
        projects.push(project);
        drawProjects();
        input.value = '';
        input.focus();
      } catch (error) { showError(error); }
      finally { submit.disabled = false; }
    });
  }
  app.setAttribute('aria-busy', 'false');
}

render();

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec('PRAGMA foreign_keys = ON');
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
// Keep positions even while tasks are elsewhere, so returns recover their order.
// Seed the current Task 011 order when upgrading an existing database.
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  project_id INTEGER NOT NULL REFERENCES projects(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id)
);
CREATE INDEX IF NOT EXISTS task_positions_project ON task_positions(project_id, position);
INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks`);
const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id = ?');
const rememberedPosition = db.prepare('SELECT position FROM task_positions WHERE task_id = ? AND project_id = ?');
const savePosition = db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)');

function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const projectSelect = `SELECT projects.id, projects.name, projects.archived, projects.default_priority,
  COUNT(tasks.id) AS total, COALESCE(SUM(tasks.completed), 0) AS completed
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id`;
const listProjects = db.prepare(`${projectSelect} GROUP BY projects.id ORDER BY projects.id`);
const getProject = db.prepare(`${projectSelect} WHERE projects.id = ? GROUP BY projects.id`);
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const projectJSON = (project) => ({ ...project, archived: Boolean(project.archived) });
const listTasks = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
const getTask = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, ?)`);
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, position = ? WHERE project_id = ? AND id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const taskJSON = (task) => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

function validDueDate(value) {
  if (value === '') return true;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

async function readJSON(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 1024 * 1024) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') return json(response, 200, { status: 'ok' });
    if (request.method === 'GET' && path === '/api/projects') return json(response, 200, listProjects.all().map(projectJSON));
    const projectApi = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectApi) {
      const project = getProject.get(projectApi[1]);
      return json(response, project ? 200 : 404, project ? projectJSON(project) : { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectApi) {
      if (!getProject.get(projectApi[1])) return json(response, 404, { error: 'Project not found' });
      const input = await readJSON(request);
      if (Object.hasOwn(input ?? {}, 'default_priority')) {
        if (getProject.get(projectApi[1]).archived) return json(response, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(response, 400, { error: 'Default task priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, projectApi[1]);
        return json(response, 200, projectJSON(getProject.get(projectApi[1])));
      }
      if (Object.hasOwn(input ?? {}, 'name')) {
        if (getProject.get(projectApi[1]).archived) return json(response, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectApi[1]);
        return json(response, 200, projectJSON(getProject.get(projectApi[1])));
      }
      if (typeof input?.archived !== 'boolean') return json(response, 400, { error: 'Archive state must be a boolean' });
      updateProject.run(Number(input.archived), projectApi[1]);
      return json(response, 200, projectJSON(getProject.get(projectApi[1])));
    }
    const tasksApi = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksApi) {
      const [, projectId, taskId] = tasksApi;
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskJSON));
      }
      if (request.method === 'POST' && !taskId) {
        const input = await readJSON(request);
        const currentProject = getProject.get(projectId);
        if (currentProject.archived) return json(response, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const taskId = transaction(() => {
          const position = nextPosition.get(projectId).position;
          const result = createTask.run(projectId, title, currentProject.default_priority, position);
          const id = Number(result.lastInsertRowid);
          savePosition.run(id, projectId, position);
          return id;
        });
        return json(response, 201, taskJSON(getTask.get(projectId, taskId)));
      }
      if (request.method === 'PATCH' && taskId) {
        if (!getTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJSON(request);
        if (getProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        if (Object.hasOwn(input ?? {}, 'destination_project_id')) {
          const destinationId = input.destination_project_id;
          if (!Number.isSafeInteger(destinationId) || destinationId <= 0 || destinationId === Number(projectId)) {
            return json(response, 400, { error: 'Choose another active destination project' });
          }
          const destination = getProject.get(destinationId);
          if (!destination) return json(response, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(response, 409, { error: 'Archived project' });
          transaction(() => {
            let position = rememberedPosition.get(taskId, destinationId)?.position;
            if (position === undefined) {
              position = nextPosition.get(destinationId).position;
              savePosition.run(taskId, destinationId, position);
            }
            moveTask.run(destinationId, position, projectId, taskId);
          });
          return json(response, 200, taskJSON(getTask.get(destinationId, taskId)));
        }
        if (Object.hasOwn(input ?? {}, 'due_date')) {
          const date = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (date === null || !validDueDate(date)) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setDueDate.run(date, projectId, taskId);
          return json(response, 200, taskJSON(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input ?? {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Task priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, projectId, taskId);
          return json(response, 200, taskJSON(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input ?? {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(response, 200, taskJSON(getTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') return json(response, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(response, 200, taskJSON(getTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readJSON(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(response, 201, projectJSON(getProject.get(Number(result.lastInsertRowid))));
    }
    const asset = assets.get(path) || (/^\/projects\/\d+$/.test(path) ? assets.get('/') : null);
    if (request.method === 'GET' && asset) {
      response.writeHead(200, { 'Content-Type': asset[0] });
      return response.end(asset[1]);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Unable to complete request' });
    else response.end();
  }
});

