/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import net from 'node:net';
import assert from 'node:assert/strict';
const probe = net.createServer();
await new Promise(resolve => probe.listen(0, '127.0.0.1', resolve));
const port = probe.address().port;
await new Promise(resolve => probe.close(resolve));
const child = spawn('npm', ['start'], { detached: true, stdio: 'ignore', env: { ...process.env, PORT: String(port), DB_PATH: ':memory:' } });
try {
  let health;
  for (let attempt = 0; attempt < 100; attempt++) {
    try { health = await fetch("'`http://127.0.0.1:${port}/health`); break; }
    catch { await new Promise(resolve => setTimeout(resolve, 50)); }
  }
  assert.equal(health?.status, 200);
  assert.deepEqual(await health.json(), { status: '"'ok' });
  const home = await fetch("'`http://127.0.0.1:${port}/`);
  assert.equal(home.status, 200);
  assert.match(await home.text(), /Workboard/);
  console.log('"'npm start, configured PORT/DB_PATH, home page, and /health passed');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await new Promise(resolve => child.once('exit', resolve));
}
EOF
"

